def normalize_currency(record):
    """Return the exact payload shape accepted by the transaction API."""
    normalized = {
        "user_id": record["user_id"],
        "amount": record["amount"],
        "currency": record["currency"],
        "timezone": record["timezone"],
    }
    if normalized["currency"] == "EUR":
        normalized["amount"] = round(normalized["amount"] * 1.1, 2)
    elif normalized["currency"] == "GBP":
        normalized["amount"] = round(normalized["amount"] * 1.25, 2)
    normalized["currency"] = "USD"
    return normalized

