import json
import numbers
from pathlib import Path

from fallback_policy import fill_system_defaults
from mock_profile_api import TRACE as PROFILE_TRACE, get_profile
from mock_transaction_api import TRACE as TX_TRACE, send_transaction
from normalization_policy import normalize_currency
from profile_merge import merge_profile
from transaction_contract import REQUIRED_FIELDS


def validate_record(record):
    """Return structured local validation errors for one input record."""
    errors = []
    if not isinstance(record, dict):
        return [{
            "field": "record",
            "error": "wrong_type",
            "message": "Each request must be an object",
        }]

    for field_name in REQUIRED_FIELDS:
        value = record.get(field_name)
        if field_name not in record or value is None:
            errors.append({
                "field": field_name,
                "error": "missing",
                "message": f"Required field '{field_name}' is missing",
            })
        elif isinstance(value, str) and not value.strip():
            errors.append({
                "field": field_name,
                "error": "empty",
                "message": f"Required field '{field_name}' must not be empty",
            })

    user_id = record.get("user_id")
    if user_id is not None and not isinstance(user_id, str):
        errors.append({
            "field": "user_id",
            "error": "wrong_type",
            "message": "'user_id' must be a string",
        })

    amount = record.get("amount")
    if amount is not None and (
        not isinstance(amount, numbers.Real) or isinstance(amount, bool)
    ):
        errors.append({
            "field": "amount",
            "error": "wrong_type",
            "message": "'amount' must be a number",
        })

    # These fields are optional inputs: null means they should be enriched or
    # filled by the fallback policy. Non-null values must still be well formed.
    for field_name in ("currency", "timezone"):
        value = record.get(field_name)
        if value is not None and (
            not isinstance(value, str) or not value.strip()
        ):
            errors.append({
                "field": field_name,
                "error": "wrong_type" if not isinstance(value, str) else "empty",
                "message": f"'{field_name}' must be a non-empty string when provided",
            })
    return errors


def enrich(record):
    try:
        profile = get_profile(record["user_id"])
    except KeyError:
        profile = {}
    merged = merge_profile(record, profile)
    return fill_system_defaults(merged)


def normalize(record):
    return normalize_currency(record)


def process_transactions(path):
    PROFILE_TRACE.clear()
    TX_TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    results = []
    for record in payload:
        errors = validate_record(record)
        if errors:
            results.append({"status": "error", "errors": errors})
            continue
        enriched = enrich(record)
        normalized = normalize(enriched)
        results.append(send_transaction(normalized))
    return {"results": results, "profile_trace": list(PROFILE_TRACE), "tx_trace": list(TX_TRACE)}
